import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const modules = ['Catalog', 'Controller', 'Features', 'Game', 'Assets', 'Inventory', 'Integrations', 'Desync', 'Music', 'UI'];
const parts = [
  '-- Nexus Hub | original implementation based on the supplied screenshots and video references.',
  '-- Generated by build.mjs. Edit src/ files and rebuild.',
  'local __factories, __cache = {}, {}',
  'local function __require(name)',
  '    if __cache[name] == nil then',
  '        assert(__factories[name], "Unknown module: " .. name)',
  '        __cache[name] = __factories[name]()',
  '    end',
  '    return __cache[name]',
  'end',
];
for (const name of modules) {
  const source = await readFile(path.join(root, 'src', `${name}.luau`), 'utf8');
  parts.push(`__factories[${JSON.stringify(name)}] = function()\n${source}\nend`);
}
const main = (await readFile(path.join(root, 'src', 'Main.client.luau'), 'utf8'))
  .replace(/require\(script\.Parent\.([A-Za-z]+)\)/g, (_, name) => {
    if (!modules.includes(name)) throw new Error(`Unknown dependency: ${name}`);
    return `__require(${JSON.stringify(name)})`;
  });
parts.push(main);
await mkdir(root, { recursive: true });
await writeFile(path.join(root, 'NexusHub.luau'), `${parts.join('\n\n')}\n`);
console.log(`NexusHub.luau gerado com ${modules.length} modulos.`);
